from importlib.util import find_spec
from importlib.metadata import PackageNotFoundError, version
from packaging.version import Version
import subprocess
import sys

PACKAGE_IMPORTS = {
    "langgraph": "langgraph",
    "langchain-core": "langchain_core",
    "langchain-openai>=1.7.2,<2.0.0": "langchain_openai",
    "requests": "requests"
}
REQUIRED_PACKAGES = [
    "langgraph",
    "langchain-core",
    "langchain-openai>=1.7.2,<2.0.0",
    "requests"
]

missing_packages = []
for package in REQUIRED_PACKAGES:
    if find_spec(PACKAGE_IMPORTS[package]) is None:
        missing_packages.append(package)
        continue
    if package.split(">", 1)[0] == "langchain-openai":
        try:
            installed_version = version("langchain-openai")
        except PackageNotFoundError:
            missing_packages.append(package)
        else:
            if Version(installed_version) < Version("1.7.2"):
                missing_packages.append(package)

if missing_packages:
    print("Installing missing packages:", ", ".join(missing_packages))
    subprocess.check_call([sys.executable, "-m", "pip", "install", "-q", *missing_packages])
else:
    print("All required packages are already available.")

